export const getProblemsByTopic = (topicId: string): Problem[] =>
  problems.filter((p) => p.topicId === topicId).sort((a, b) => a.order - b.order);

export const getProblemById = (id: string): Problem | undefined =>
  problems.find((p) => p.id === id);
